import pandas as pd, numpy as np
import plotly.graph_objs as go
from plotly.express._core import build_dataframe
from plotly.express._special_inputs import Constant, Range
from plotly.express._core import NO_COLOR

def base(df,**over):
 d={'data_frame':df,'x':None,'y':None,'color':None,'orientation':None,'category_orders':{},'labels':{},'custom_data':None,'hover_data':None,'size':None,'text':None,'path':None,'values':None,'names':None,'parents':None,'ids':None,'wide_variable':None,'wide_cross':None,'animation_frame':None,'facet_row':None,'facet_col':None,'line_group':None,'line_dash':None,'symbol':None,'pattern_shape':None,'base':None,'z':None,'a':None,'b':None,'c':None,'r':None,'theta':None,'x_start':None,'x_end':None,'error_x':None,'error_x_minus':None,'error_y':None,'error_y_minus':None,'error_z':None,'error_z_minus':None,'lat':None,'lon':None,'locations':None,'animation_group':None,'hover_name':None,'dimensions':None,'histfunc':None,'histnorm':None,'nbins':None,'text_auto':False,'marginal':None,'opacity':None,'lines':True,'markers':False,'line_shape':None,'log_x':None,'log_y':None}
 d.update(over); return d

df=pd.DataFrame({'x':[1,2,3],'y':[4,5,6],'cat':['a','b','a'],'foo':[7,8,9]})
a=base(df[['y','foo']]); build_dataframe(a,go.Scatter); print('allwide',a['x'],a['y'],a['color'],a['data_frame'].to_native())
a=base(df,x=Constant(5, label='five'),y=Range(label='idx')); build_dataframe(a,go.Scatter); print('special',a['x'],a['y'],a['data_frame'].to_native())
for color in ['cat',NO_COLOR]:
 a=base(df,x='x',y='y',color=color); build_dataframe(a,go.Scatter); print('color',color,'->',a['color'])
for over in [dict(x='missing',y='y'),dict(x=[1,2],y=[1,2,3]),dict(x=['x','y'],y='cat')]:
 a=base(df,**over)
 try: build_dataframe(a,go.Scatter); print('no err',over,a['data_frame'].to_native())
 except Exception as e: print('err',over,type(e).__name__,e)
a=base(None,x=[1,2,3],y=[4,5,6]); build_dataframe(a,go.Scatter); print('nodf',a['x'],a['data_frame'].to_native())
a=base(None,x=[1,2],y=[1,2,3]);
try: build_dataframe(a,go.Scatter); print('no err nodf')
except Exception as e: print('nodf err',type(e).__name__,e)
# wide mixed
try: build_dataframe(base(df,x=['y','cat']),go.Scatter)
except Exception as e: print('mixed',type(e).__name__,e)
PY"}

