try: px.scatter(df,x='x',y='y',marginal_x='heatmap')
except Exception as e: print('bad marginal',type(e).__name__,e)
try: px.ecdf(df,x='x',ecdfnorm='bad')
except Exception as e: print('bad ecdf',type(e).__name__,e)
PY

