import pandas as pd, plotly.express as px
from plotly.express import Constant, Range, NO_COLOR
df=pd.DataFrame({'x':[1,2,3],'a':[1,2,3],'b':[3,2,1],'cat':['u','v','w']})
for kwargs in [dict(x='x',y=['a','b']),dict(x=['a','b']),dict(y=['a','b'])]:
 f=px.line(df,**kwargs)
 print(kwargs,len(f.data),[(t.name,t.x.tolist() if t.x is not None else None,t.y.tolist() if t.y is not None else None,t.legendgroup) for t in f.data],f.data[0].hovertemplate)
f=px.scatter(df,x=Constant('const',label='C'),y=Range(label='R'))
